CREATE TABLE municipalities(id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE neighborhoods(id text PRIMARY KEY, municipality_id text NOT NULL REFERENCES municipalities, name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE accounts(id uuid PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, neighborhood_id text NOT NULL REFERENCES neighborhoods, reminders boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE follows(account_id uuid REFERENCES accounts, neighborhood_id text REFERENCES neighborhoods, PRIMARY KEY(account_id,neighborhood_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_account ON sessions(account_id);
CREATE TABLE roles(id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts, municipality_id text NOT NULL REFERENCES municipalities, neighborhood_id text REFERENCES neighborhoods, role text NOT NULL CHECK(role IN ('admin','moderator')), granted_by uuid REFERENCES accounts, revoked_at timestamptz, CHECK((role='admin' AND neighborhood_id IS NULL) OR (role='moderator' AND neighborhood_id IS NOT NULL)));
CREATE UNIQUE INDEX roles_active ON roles(account_id,municipality_id,COALESCE(neighborhood_id,''),role) WHERE revoked_at IS NULL;
CREATE TABLE posts(id uuid PRIMARY KEY, author_id uuid NOT NULL REFERENCES accounts, neighborhood_id text NOT NULL REFERENCES neighborhoods, kind text NOT NULL CHECK(kind IN ('event','notice','official')), title text NOT NULL, description text NOT NULL, location text NOT NULL, category text NOT NULL DEFAULT 'ajuda', state text NOT NULL DEFAULT 'aberto', visibility text NOT NULL DEFAULT 'visible' CHECK(visibility IN ('visible','hidden','removed')), starts_at timestamptz, ends_at timestamptz, capacity integer CHECK(capacity BETWEEN 1 AND 5000), issuer text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(kind <> 'event' OR (starts_at IS NOT NULL AND ends_at > starts_at)));
CREATE INDEX posts_feed ON posts(neighborhood_id,created_at DESC) WHERE visibility='visible';
CREATE TABLE participations(post_id uuid REFERENCES posts, account_id uuid REFERENCES accounts, active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(post_id,account_id));
CREATE TABLE replies(id uuid PRIMARY KEY, post_id uuid NOT NULL REFERENCES posts, author_id uuid NOT NULL REFERENCES accounts, body text NOT NULL, visibility text NOT NULL DEFAULT 'visible', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports(id uuid PRIMARY KEY, post_id uuid NOT NULL REFERENCES posts, reply_id uuid REFERENCES replies, reporter_id uuid NOT NULL REFERENCES accounts, reason text NOT NULL, state text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES accounts, post_id uuid REFERENCES posts, action text NOT NULL, reason text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE appeals(id uuid PRIMARY KEY, action_id uuid NOT NULL REFERENCES audit, author_id uuid NOT NULL REFERENCES accounts, reason text NOT NULL, state text NOT NULL DEFAULT 'open', UNIQUE(action_id,author_id));
CREATE TABLE notifications(id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts, post_id uuid REFERENCES posts, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
